using Ariadne.NET.Sync;

using ZeroAlloc.Inject;

[assembly: ZeroAllocInject("AddAriadneNETGeneratedServices")]

namespace Microsoft.Extensions.DependencyInjection;

/// <summary>Registers the engine's services.</summary>
public static class AriadneNETServiceCollectionExtensions
{
    /// <summary>
    /// Registers every engine service. The attribute-driven registrations come from ZeroAlloc.Inject; the
    /// git client is added here because its implementation is the ZeroAlloc.Resilience proxy around
    /// <see cref="GitCliClient"/>, which ZeroAlloc.Inject cannot see, as it is generated by another generator.
    /// The ZeroAlloc.Telemetry proxies need no registration: the public pack services and the sync provider call them
    /// through <c>PackOperations.Instrumented</c> and <c>SyncOperations.Instrumented</c>.
    /// </summary>
    public static IServiceCollection AddAriadneNETServices(this IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);

        services.AddAriadneNETGeneratedServices();
        services.AddGitClientResilience<GitCliClient>();
        return services;
    }
}
